<?php // Q5b: how each validator treats {"type":"string","format":"uri"} (the only format the schema uses, 65 times) against RFC 3986 verdicts, and the schema's "^...{43}$" pattern with a trailing newline. Usage: php q5b_format_pattern.php <opis dir> <jr dir>
require "$argv[1]/vendor/autoload.php"; require "$argv[2]/vendor/autoload.php";
$C = ['https://trust.example/issuers/finance' => 1, 'urn:uuid:8381317d-882e-4292-ae88-24d8f0b78f60' => 1, 'did:key:z6MkhaXgBZDvotDkL5257faiztiGiC2QtKLGpbnnEGta2doK' => 1, 'mailto:user@example.com' => 1, 'a:b' => 1, 'https://[2001:db8::1]:8443/p?q=1#f' => 1, 'https://user@host.example:80/p' => 1,
    'https://host.example/a%20b' => 1, 'file:///etc/hosts' => 1, 'not a uri' => 0, '/relative/path' => 0, 'https://exa mple/' => 0, 'https://host/%zz' => 0, '' => 0, 'http://[::1' => 0, '1http://x' => 0, 'https://host/\\path' => 0, "https://host/\u{fc}" => 0, 'https://host:port/' => 0, "https://host/\n" => 0];
$schema = (object) ['type' => 'string', 'format' => 'uri']; $opis = new Opis\JsonSchema\Validator();
$jr = function (string $s) use ($schema) { $v = new JsonSchema\Validator(); $v->validate($s, $schema); return $v->isValid(); };
$impl = ['expected (RFC 3986)' => fn($s) => null, 'opis 2.6.0' => fn($s) => $opis->validate($s, $schema)->isValid(), 'justinrainbow 6.13.1' => $jr, 'filter_var URL' => fn($s) => filter_var($s, FILTER_VALIDATE_URL) !== false,
    'Uri\Rfc3986\Uri (8.5+)' => fn($s) => class_exists('Uri\Rfc3986\Uri') ? Uri\Rfc3986\Uri::parse($s) !== null : null];
printf("%-60s", 'input'); foreach (array_slice($impl, 1) as $n => $_) printf(' %-22s', $n); echo "\n";
foreach ($C as $s => $want) { printf('%-60s', ($want ? 'valid   ' : 'invalid ') . json_encode((string) $s, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE)); foreach (array_slice($impl, 1) as $f) { $r = $f((string) $s); printf(' %-22s', $r === null ? 'n/a' : ($r === (bool) $want ? 'ok' : 'WRONG (' . ($r ? 'accepts' : 'rejects') . ')')); } echo "\n"; }
foreach (array_slice($impl, 1) as $n => $f) { if (!class_exists("Uri\\Rfc3986\\Uri") && str_starts_with($n, "Uri")) { echo "$n: n/a, class absent on PHP " . PHP_VERSION . "\n"; continue; } $w = count(array_filter(array_keys($C), fn($s) => ($r = $f((string) $s)) !== null && $r !== (bool) $C[$s])); echo "$n: $w of ", count($C), " differ from the RFC 3986 verdict\n"; }
$pat = (object) ['type' => 'string', 'pattern' => '^[A-Za-z0-9_-]{43}$']; $d = str_repeat('A', 43); echo "pattern ^[A-Za-z0-9_-]{43}\$ (body_digest in the schema), value = 43 characters plus a suffix:\n";
foreach (['' => 'none', "\n" => '"\n"', "\n\n" => '"\n\n"', "\r\n" => '"\r\n"'] as $suffix => $label) { $j = new JsonSchema\Validator(); $s = $d . $suffix; $j->validate($s, $pat);
    printf("  suffix %-8s opis %-8s justinrainbow %-8s preg_match('/^..\$/') %d  preg_match('/^..\$/D') %d\n", $label, $opis->validate($s, $pat)->isValid() ? 'accepts' : 'rejects', $j->isValid() ? 'accepts' : 'rejects', preg_match('/^[A-Za-z0-9_-]{43}$/', $s), preg_match('/^[A-Za-z0-9_-]{43}$/D', $s)); }
